70	
71	\begin{enumerate}
72	    \item \textbf{设置严格的防护栏}：代码库中的测试 + CI/CD 最佳实践是不可或缺的 backstop
73	    \item \textbf{审计每个 Agent 的修改}：标记（label）每个由 Agent 产生的 diff
74	    \item \textbf{不同任务使用不同模型}：简单任务用快速模型，复杂任务用强模型
75	    \item \textbf{复杂任务需要更多前期引导}：不是所有任务都适合完全异步委派
76	    \item \textbf{频繁 checkpoint（commit）}：定期提交代码，防止 Agent 偏离方向时丢失进展
77	\end{enumerate}
78	
79	\begin{warningbox}{开放问题}
80	\begin{itemize}
81	    \item 如何自动化每个任务最初 10--20\% 的调研阶段？
82	    \item 如何维护一个待执行任务的队列？（对于一次性修改较容易，但对持续性工作流仍是挑战）
83	\end{itemize}
84	\end{warningbox}
